style.css:
@-moz-document url-prefix("https://www.youtube.com/") {
/* Background with Gojo image */
  body {
    background: url("https://i.ibb.co/PhQSTvV/gojo-wallpaper.jpg") no-repeat center center fixed !important;
    background-size: cover !important;
  }

  /* Overlay animated gradient aura */
  body::before {
    content: "";
    position: fixed;
    top: 0; left: 0;
    width: 100%; height: 100%;
    background: radial-gradient(circle, rgba(0,255,255,0.25), transparent 70%);
    animation: gojoAura 6s infinite alternate;
    pointer-events: none;
    z-index: 0;
  }

  @keyframes gojoAura {
    from { transform: scale(1); opacity: 0.7; }
    to   { transform: scale(1.2); opacity: 0.4; }
  }

  /* Floating Gojo watermark */
  body::after {
    content: "";
    position: fixed;
    bottom: 20px; right: 20px;
    width: 150px; height: 150px;
    background: url("https://i.ibb.co/4NtL5nR/gojo-sticker.png") no-repeat center;
    background-size: contain;
    opacity: 0.9;
    animation: floatGojo 8s ease-in-out infinite;
    pointer-events: none;
    z-index: 10;
  }

  @keyframes floatGojo {
    0%, 100% { transform: translateY(0); }
    50%      { transform: translateY(-15px); }
  }

  /* Video titles */
  #video-title {
    color: #00faff !important;
    text-shadow: 0 0 10px #00faff, 0 0 20px #0066ff;
    font-weight: bold !important;
    transition: transform 0.2s ease;
  }
  #video-title:hover {
    transform: scale(1.05);
    color: #ffffff !important;
  }

  /* Search box glow */
  input#search {
    background: rgba(0,0,0,0.7) !important;
    border: 2px solid #00faff !important;
    border-radius: 12px !important;
    color: #fff !important;
    box-shadow: 0 0 12px #00faff;
  }

  /* Buttons glow */
  #buttons ytd-button-renderer.style-scope {
    filter: drop-shadow(0 0 6px #00faff);
  }

  /* Hide annoying background layer */
  ytd-masthead, ytd-app {
    background: transparent !important;
  }
}
